const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const poyangLake = ee.Geometry.Rectangle([115.5, 28.5, 116.5, 29.5]); // Poyang Lake bounding box
  const date1 = '2022-07-10';
  const date2 = '2022-08-27';

  // 2. Data Acquisition - Sentinel-2 Surface Reflectance
  const s2_col1 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(poyangLake)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'));

  const s2_col2 = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(poyangLake)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'));

  // Check if collections have data
  const size1 = s2_col1.size().getInfo();
  const size2 = s2_col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    print(`July 10 Images: ${size1}, August 27 Images: ${size2}`);
    print("<answer>C1</answer>");
    return;
  }

  // Get least cloudy images
  const img1 = s2_col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2 = s2_col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Processing - Cloud masking and water detection
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function calculateWaterArea(img) {
    const cloudMasked = maskClouds(img);

    // Calculate NDWI for water detection
    const ndwi = cloudMasked.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0 indicates water)
    const waterMask = ndwi.gt(0);

    // Calculate water area in square meters
    const areaStats = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: poyangLake,
      scale: 20,
      maxPixels: 1e9
    });

    const waterPixels = areaStats.get('NDWI');
    const waterArea = ee.Number(waterPixels).multiply(20 * 20); // Convert pixels to m²

    // Count total valid pixels after masking
    const validStats = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: poyangLake,
      scale: 20,
      maxPixels: 1e9
    });

    return {
      area: waterArea,
      validPixels: validStats.get('NDWI'),
      cloudPercent: img.get('CLOUDY_PIXEL_PERCENTAGE')
    };
  }

  // Calculate water areas
  const result1 = calculateWaterArea(img1);
  const result2 = calculateWaterArea(img2);

  const area1 = result1.area.getInfo();
  const area2 = result2.area.getInfo();
  const valid1 = result1.validPixels.getInfo();
  const valid2 = result2.validPixels.getInfo();
  const cloud1 = result1.cloudPercent.getInfo();
  const cloud2 = result2.cloudPercent.getInfo();

  print(`July 10: Area=${(area1/1e6).toFixed(1)} km², Valid=${valid1}, Cloud=${cloud1}%`);
  print(`August 27: Area=${(area2/1e6).toFixed(1)} km², Valid=${valid2}, Cloud=${cloud2}%`);

  // 4. Validation & Final Answer
  if (valid1 === 0 || valid2 === 0) {
    print("<answer>C2</answer>");
  } else if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    print("<answer>C3</answer>");
  } else if (area2 < area1) {
    print(`Decrease: ${((area1-area2)/1e6).toFixed(1)} km²`);
    print("<answer>A</answer>");
  } else {
    print(`No decrease or increase: ${((area2-area1)/1e6).toFixed(1)} km²`);
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
